"""Triton implementation of aten::special_scaled_modified_bessel_k0.

K0e(x) = exp(x) * K0(x), evaluated with region-wise approximations so the
exponential scaling is folded in and never overflows:

  A) 0 < x <= 1.5 : K0e = exp(x) * ( S(y) + (ln2 - gamma - log(x)) * I0(y) )
                    with y = x^2/4 and I0/S the exact Taylor series of the
                    modified Bessel I0 and of its harmonic-weighted companion.
                    For x <= 1.5 (y <= 0.5625) both series converge factorially,
                    so six terms are far below float32 resolution and the two
                    terms cancel by a factor <= 2 at the region edge.
  B) 1.5 < x <= 2.5: one degree-8 Chebyshev polynomial in t = 2(x-2). This is
                    the band where the log/series form loses more than a digit
                    to cancellation, so a direct fit is used instead.
  C) x > 2.5      : K0e = Q(2/x) / sqrt(x), the classic 1/x fit whose leading
                    term is sqrt(pi/2); exp() never appears here.

Integral/bool/float64 inputs are first promoted to one contiguous float32
workspace by a device kernel (both the dtype promotion and the layout gather),
so the arithmetic kernel has a single float32 specialisation.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 1024
_SMALL_BLOCK = 128
_NWARPS = 4
_RANK = 6


@triton.jit
def _k0e(v):
    """K0e for a float32 vector, branchless with ordered edge fixups."""

    # --- region A: I0 and S as series in y2 = v*v (the 1/4 of y = v^2/4 is
    # folded into the coefficients). Truncated at k=5: at the region edge
    # y=0.5625 the dropped terms are 6e-8 (I0) and 2e-7 (S) relative.
    y2 = v * v
    i0 = 6.781684028e-08
    i0 = i0 * y2 + 6.781684028e-06
    i0 = i0 * y2 + 4.340277778e-04
    i0 = i0 * y2 + 1.562500000e-02
    i0 = i0 * y2 + 2.500000000e-01
    i0 = i0 * y2 + 1.0

    s = 1.548484520e-07
    s = s * y2 + 1.412850839e-05
    s = s * y2 + 7.957175926e-04
    s = s * y2 + 2.343750000e-02
    s = s * y2 + 2.500000000e-01
    s = s * y2

    # log(v) - ln(2) is folded into log(v) + (ln2 - gamma) so no subnormal v/2
    # is formed; log(v) already gives -inf at v == 0 (and at -0.0) and NaN for
    # v < 0, so the pole and the negative branch need no separate fixup.
    small = tl.exp(v) * (s + (0.11593151565841244 - tl.log(v)) * i0)

    # --- regions B+C merged: one degree-7 fit of Q(u) = K0e(2/u)*sqrt(2/u)
    # over u = 2/x in (0, 4/3], i.e. the whole x > 1.5 half line. Fitted
    # against a 60-digit oracle: max relative error 4.5e-8. rq = 1/sqrt(x)
    # also gives 2/x = 2 rq^2, so no divide is needed.
    rq = tl.rsqrt(v)
    u = 2.0 * rq * rq
    q = -1.739420665e-04
    q = q * u + 1.122547070e-03
    q = q * u - 3.319336217e-03
    q = q * u + 6.442901076e-03
    q = q * u - 1.084044278e-02
    q = q * u + 2.193799413e-02
    q = q * u - 7.832660511e-02
    q = q * u + 1.253314080e00
    large = q * rq

    return tl.where(v <= 1.5, small, large)


@triton.jit
def _offset(lin, s0, s1, s2, s3, s4, s5, t0, t1, t2, t3, t4, t5):
    """Row-major index decomposition of a flattened offset (rank <= 6)."""
    rem = lin.to(tl.int64)
    i5 = rem % s5
    rem = rem // s5
    off = i5 * t5
    i4 = rem % s4
    rem = rem // s4
    off += i4 * t4
    i3 = rem % s3
    rem = rem // s3
    off += i3 * t3
    i2 = rem % s2
    rem = rem // s2
    off += i2 * t2
    i1 = rem % s1
    rem = rem // s1
    off += i1 * t1
    off += rem * t0
    return off


@triton.jit
def _prepare_kernel(
    x_ptr,
    out_ptr,
    numel,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xt0,
    xt1,
    xt2,
    xt3,
    xt4,
    xt5,
    STRIDED: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Dtype promotion + layout gather into one contiguous float32 workspace."""
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    if STRIDED:
        xo = _offset(offs, xs0, xs1, xs2, xs3, xs4, xs5, xt0, xt1, xt2, xt3, xt4, xt5)
    else:
        xo = offs
    v = tl.load(x_ptr + xo, mask=mask, other=0)
    tl.store(out_ptr + offs, v.to(tl.float32), mask=mask)


@triton.jit
def _k0e_flat_kernel(
    x_ptr,
    out_ptr,
    numel,
    BLOCK: tl.constexpr,
    IDX64: tl.constexpr,
    EVEN: tl.constexpr,
):
    pid = tl.program_id(0)
    if IDX64:
        offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        # numel is a whole multiple of BLOCK: no tail, so both the load and the
        # store are unpredicated.
        r = _k0e(tl.load(x_ptr + offs))
        tl.store(out_ptr + offs, r.to(out_ptr.dtype.element_ty))
    else:
        mask = offs < numel
        r = _k0e(tl.load(x_ptr + offs, mask=mask, other=1.0))
        tl.store(out_ptr + offs, r.to(out_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _k0e_strided_kernel(
    x_ptr,
    out_ptr,
    numel,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xt0,
    xt1,
    xt2,
    xt3,
    xt4,
    xt5,
    os0,
    os1,
    os2,
    os3,
    os4,
    os5,
    ot0,
    ot1,
    ot2,
    ot3,
    ot4,
    ot5,
    X_STRIDED: tl.constexpr,
    OUT_CONTIG: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    if X_STRIDED:
        xo = _offset(offs, xs0, xs1, xs2, xs3, xs4, xs5, xt0, xt1, xt2, xt3, xt4, xt5)
    else:
        xo = offs
    v = tl.load(x_ptr + xo, mask=mask, other=1.0)
    r = _k0e(v)
    if OUT_CONTIG:
        tl.store(out_ptr + offs, r.to(out_ptr.dtype.element_ty), mask=mask)
    else:
        oo = _offset(offs, os0, os1, os2, os3, os4, os5, ot0, ot1, ot2, ot3, ot4, ot5)
        tl.store(out_ptr + oo, r.to(out_ptr.dtype.element_ty), mask=mask)


def _pad6(shape, stride):
    sizes = [1] * _RANK
    strides = [0] * _RANK
    for i in range(len(shape)):
        sizes[i] = int(shape[i])
        strides[i] = int(stride[i])
    return sizes, strides


_FLAT_SIZES = [1, 1, 1, 1, 1, 1]
_FLAT_STRIDES = [0, 0, 0, 0, 0, 0]


def special_scaled_modified_bessel_k0(x, *, out=None):
    if not isinstance(x, torch.Tensor):
        raise TypeError(
            "special_scaled_modified_bessel_k0(): argument 'x' must be Tensor, not "
            + type(x).__name__
        )
    if not x.is_cuda:
        raise ValueError(
            "special_scaled_modified_bessel_k0: input tensor must be a device tensor"
        )

    dt = x.dtype
    if dt is torch.float32:
        res_dtype = torch.float32
    elif dt is torch.float64:
        res_dtype = torch.float64
    elif dt.is_floating_point or dt.is_complex:
        raise RuntimeError(
            "\"scaled_modified_bessel_k0_cuda\" not implemented for '%s'" % str(dt)
        )
    else:
        res_dtype = torch.float32

    numel = x.numel()
    if out is not None:
        if not isinstance(out, torch.Tensor):
            raise TypeError(
                "special_scaled_modified_bessel_k0.out(): argument 'out' must be Tensor"
            )
        if not out.is_floating_point():
            raise RuntimeError(
                "result type Float can't be cast to the desired output type %s"
                % str(out.dtype).replace("torch.", "").capitalize()
            )
        if out.numel() != numel:
            raise ValueError(
                "special_scaled_modified_bessel_k0.out(): output tensor has wrong size"
            )
        if out.device != x.device:
            raise ValueError(
                "special_scaled_modified_bessel_k0.out(): expected all tensors on one device"
            )
        result = out
    else:
        result = torch.empty(x.shape, dtype=res_dtype, device=x.device)

    if numel == 0:
        return result
    if x.dim() > _RANK:
        raise RuntimeError(
            "special_scaled_modified_bessel_k0: input rank above %d is not supported"
            % _RANK
        )

    grid = (triton.cdiv(numel, _BLOCK),)
    x32 = x
    x_strided = False
    if dt is not torch.float32 or not x.is_contiguous():
        xv = x.view(torch.uint8) if dt is torch.bool else x
        ws = torch.empty(x.shape, dtype=torch.float32, device=x.device)
        if x.is_contiguous():
            sizes, strides = _FLAT_SIZES, _FLAT_STRIDES
            _prepare_kernel[grid](
                xv,
                ws,
                numel,
                sizes[0],
                sizes[1],
                sizes[2],
                sizes[3],
                sizes[4],
                sizes[5],
                strides[0],
                strides[1],
                strides[2],
                strides[3],
                strides[4],
                strides[5],
                STRIDED=False,
                BLOCK=_BLOCK,
                num_warps=_NWARPS,
            )
        else:
            sizes, strides = _pad6(x.shape, x.stride())
            _prepare_kernel[grid](
                xv,
                ws,
                numel,
                sizes[0],
                sizes[1],
                sizes[2],
                sizes[3],
                sizes[4],
                sizes[5],
                strides[0],
                strides[1],
                strides[2],
                strides[3],
                strides[4],
                strides[5],
                STRIDED=True,
                BLOCK=_BLOCK,
                num_warps=_NWARPS,
            )
        x32 = ws

    if x32.is_contiguous() and result.is_contiguous():
        # Per-CTA work is what this device rewards (a 256-element block was
        # 3.3x slower, 2048 was 13.5% faster than 1024), so the block size
        # grows with the tensor. The unpredicated variant is only taken when
        # the element count divides the chosen block size exactly.
        if numel >= 4194304:
            blk = 8192
            even = numel % 8192 == 0
        elif numel >= 1048576:
            blk = 4096
            even = numel % 4096 == 0
        elif numel >= 65536:
            blk = 2048
            even = numel % 2048 == 0
        else:
            blk = _BLOCK
            even = False
